package dev.zomboid.gore;
import java.util.*;
/** Occasional, shallow visual tissue loss. Native First Aid remains authoritative. */
public final class Bite48 {
 static boolean torn(int[] a,int k){return a[k+4]==2&&Math.floorMod(Objects.hash(a[k],a[k+1],a[k+2],a[k+3]),4)==0;}
 static List<Mesh12.Box> holes(int[] marks,int region,Mesh12.Box b){List<Mesh12.Box> holes=new ArrayList<>();for(int k=0;k+6<marks.length;k+=7){if(!torn(marks,k)||marks[k+5]<=0)continue;int cl=marks[k],r=switch(cl){case 0->0;case 1->2;case 2,3->4;case 4->6;case 5->3;default->5;};if(r!=region)continue;double[]q={marks[k+1]/255d,marks[k+2]/255d,marks[k+3]/255d};if(cl==3||cl==7)q[1]=.75+q[1]*.25;else if(cl==2||cl==6)q[1]*=.75;float[]min={b.x0(),b.y0(),b.z0()},max={b.x1(),b.y1(),b.z1()},p=new float[3];int axis=0;double edge=1;boolean high=false;for(int a=0;a<3;a++){p[a]=(float)(min[a]+q[a]*(max[a]-min[a]));if(q[a]<edge){axis=a;edge=q[a];high=false;}if(1-q[a]<edge){axis=a;edge=1-q[a];high=true;}}float size=1.25f*Math.min(1,marks[k+5]/12000f);float[]lo=new float[3],hi=new float[3];for(int a=0;a<3;a++){lo[a]=p[a]-size;hi[a]=p[a]+size;}if(high){lo[axis]=max[axis]-size*.8f;hi[axis]=max[axis]+1;}else{lo[axis]=min[axis]-1;hi[axis]=min[axis]+size*.8f;}holes.add(new Mesh12.Box(lo[0],lo[1],lo[2],hi[0],hi[1],hi[2]));}return holes;}
 public static boolean render(Object part,Object pose,Object vc,int light,int overlay,int color){Player45.Context ctx=Player45.CURRENT.get();if(ctx==null||ctx.parts==null)return false;Integer region=ctx.parts.get(part);if(region==null||!R.yes(R.get(part,"visible"))||R.yes(R.get(part,"skipDraw")))return false;List<Mesh12.Cube> cubes=Model25.cubes(part,region);if(cubes.isEmpty())return false;Mesh12.Box b=CSG24.bounds(cubes);List<Mesh12.Box> holes=holes(ctx.marks,region,b);if(holes.isEmpty())return false;List<Mesh12.Quad> mesh=new ArrayList<>();for(Mesh12.Cube cube:cubes)for(Mesh12.Face f:cube.faces())CSG24.surface(mesh,f,holes);R.call(pose,"pushPose");try{R.call(part,"translateAndRotate",pose);Object p=R.call(pose,"last");emit(mesh,vc,p,light,overlay,color);if(!Model25.LAYERS.contains(part)){List<Mesh12.Quad> flesh=new ArrayList<>();for(Mesh12.Box hole:holes){Mesh12.Box h=Mesh12.intersect(b,hole);if(h.valid()){float inset=.16f;Mesh12.Box inside=new Mesh12.Box(h.x0()+inset,h.y0()+inset,h.z0()+inset,h.x1()-inset,h.y1()-inset,h.z1()-inset);if(inside.valid())Mesh12.box(flesh,inside,1,null);}}Object tex=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_gore","textures/entity/medical45.png");Object fleshVC=R.call(ctx.buffer,"getBuffer",R.call(R.type("net.minecraft.client.renderer.RenderType"),"entityCutoutNoCull",tex));emit(flesh,fleshVC,p,light,overlay,0xff942c35);}}finally{R.call(pose,"popPose");}return true;}
 static void emit(List<Mesh12.Quad> mesh,Object vc,Object p,int light,int overlay,int color){for(Mesh12.Quad q:mesh)for(Mesh12.Vertex v:q.vertices()){Object vv=R.call(vc,"addVertex",p,v.x()/16,v.y()/16,v.z()/16);R.call(vv,"setColor",color);R.call(vv,"setUv",v.u(),v.v());R.call(vv,"setOverlay",overlay);R.call(vv,"setLight",light);R.call(vv,"setNormal",p,q.nx(),q.ny(),q.nz());}}
}
